import{_ as a,o as t,c as l,a4 as o}from"./chunks/framework.DzJZdBQK.js";const _=JSON.parse('{"title":"写作课作业-111","description":"","frontmatter":{"date":"2021-03-06T21:01:23","title":"写作课作业-111","categories":["写作","作业","区块链小白书"],"tags":["写作","作业","区块链小白书"]},"headers":[{"level":2,"title":"2W1H","slug":"_2w1h","link":"#_2w1h","children":[{"level":3,"title":"What","slug":"what","link":"#what","children":[]},{"level":3,"title":"Why","slug":"why","link":"#why","children":[]},{"level":3,"title":"How","slug":"how","link":"#how","children":[]}]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/111.md","filePath":"posts/homework/111.md"}'),h={name:"posts/homework/111.md"};function r(i,e,n,s,p,c){return t(),l("div",null,[...e[0]||(e[0]=[o('<blockquote><p>《区块链小白书》之《比特币 7.挖矿是怎么回事》</p></blockquote><h2 id="_2w1h" tabindex="-1">2W1H <a class="header-anchor" href="#_2w1h" aria-label="Permalink to &quot;2W1H&quot;">​</a></h2><h3 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h3><p>通过架设比特币节点获利的过程，被人们形象的称为“挖矿”。</p><h3 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h3><p>使用分布式管理账簿的方式，节点数量越多，网络越安全。比特币银行通过发放比特币奖励的吸引大家参与分布式网络的建设，参与网络维护的节点还可以通过分享网络转账手续费获益。</p><blockquote><p>按照约定，每个区块的第一笔交易是一个特殊的交易，它会生成一枚新的硬币，所属权是这个区块的生成者。这么做，使得节点支持网络有所奖励，也提供了一种将硬币发行到流通之中的方式 —— 在这个系统中，反正也没有一个中心化的权威方去发行那些硬币。如此这般稳定地增加一定数量的新硬币进入流通，就好像是黄金开采者不断耗用他们的资源往流通之中增加黄金一样。在我们的系统中，被耗用的资源是 CPU 工作时间和它们所用的电力。</p></blockquote><h3 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h3><p>通过提问的方式“人家凭什么来参与呢？”引出比特币网络的工作机制，比特币网络每10分钟需要完成一个账簿，对于最先准确无误完成区块生成的节点，可以获得比特币的奖励。而比特币银行通过发放奖励的来完成货币的发行。比特币总量2100万个，总计发送142年，刚开始每10分钟发50个，以后每4年减半一次。红包全部发完之后，参与网络维护的节点依然可以通过分享网络转账手续费而获益。通过架设比特币节点获利的过程，被人们形象的称为“挖矿”。然后描述了挖矿的难度越大越大，对算力的要求越来越高。</p><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>前些日子听到有人在慨叹，之前笔记本都能挖比特币的时候，自己没有去挖矿，现在想挖也挖不了，想买又觉得太贵了，我想他只是被比特币上涨的新闻所吸引。就像最近茅台一直涨，大家也在说之前没买茅台一样。对于自己来说，因为自己的认知不够，是不懂比特币的价值错过了，俗话说种树最好的时间是十年前，其次是现在，那现在通过定投BOX和使用水龙头的方式，慢慢获取比特币，慢慢看着树长大好了。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',18)])])}const u=a(h,[["render",r]]);export{_ as __pageData,u as default};
